def split_csv(line):
    n = len(line)
    if n == 0:
        return [""]

    fields = []
    i = 0

    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            field_chars = []
            while True:
                if i >= n:
                    return None  # unterminated quoted field
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        field_chars.append('"')
                        i += 2
                        continue
                    else:
                        i += 1  # consume closing quote
                        break
                else:
                    field_chars.append(c)
                    i += 1
            # After closing quote, must be comma or end of line
            if i < n:
                if line[i] == ',':
                    fields.append(''.join(field_chars))
                    i += 1
                    if i == n:
                        fields.append('')  # trailing comma -> empty field
                        break
                    else:
                        continue
                else:
                    return None  # malformed: something after closing quote
            else:
                fields.append(''.join(field_chars))
                break
        else:
            # unquoted field
            start = i
            while i < n and line[i] != ',' and line[i] != '"':
                i += 1
            if i < n and line[i] == '"':
                return None  # quote not allowed inside unquoted field
            field = line[start:i]
            fields.append(field)
            if i < n and line[i] == ',':
                i += 1
                if i == n:
                    fields.append('')
                    break
                else:
                    continue
            else:
                break

    return fields

